import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{o as a,c as s,e as n}from"./app-09e0be14.js";const t={},o=n(`<h1 id="fastfetch-快速显示系统信息的工具-类-neofetch" tabindex="-1"><a class="header-anchor" href="#fastfetch-快速显示系统信息的工具-类-neofetch" aria-hidden="true">#</a> fastfetch（快速显示系统信息的工具（类 neofetch））</h1><blockquote><p>Homebrew 版本 2.55.1 ｜ 主页：见官方文档 ｜ 安装：<code>brew install fastfetch</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>fastfetch 是一个用 C 语言编写的高性能系统信息采集工具，在终端里以 ASCII 艺术或字符 Logo 的形式展示操作系统、内核、CPU、内存、磁盘、GPU、Shell、桌面环境等关键信息。它定位为 neofetch 的更快替代品，启动速度极快（通常只需几毫秒），非常适合在 shell 启动配置（如 <code>.bashrc</code>、<code>.zshrc</code>）中调用，或者在展示终端截图时生成美观的系统信息面板。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> fastfetch

<span class="token comment"># 升级</span>
brew upgrade fastfetch

<span class="token comment"># 卸载</span>
brew uninstall fastfetch

<span class="token comment"># 验证安装成功（查看版本号）</span>
fastfetch <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>安装成功后，终端里直接输入 <code>fastfetch</code> 即可显示系统信息。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>参数说明</th><th>示例</th></tr></thead><tbody><tr><td><code>fastfetch</code></td><td>无参数，默认输出完整系统信息</td><td><code>fastfetch</code></td></tr><tr><td><code>fastfetch --logo</code></td><td>指定 logo 样式（如 <code>none</code> 隐藏 logo）</td><td><code>fastfetch --logo none</code></td></tr><tr><td><code>fastfetch --structure</code></td><td>自定义输出结构（逗号分隔的模块顺序）</td><td><code>fastfetch --structure OS:Host:CPU:GPU:Memory</code></td></tr><tr><td><code>fastfetch --format json</code></td><td>以 JSON 格式输出，便于脚本解析</td><td><code>fastfetch --format json</code></td></tr><tr><td><code>fastfetch --format jsonc</code></td><td>以 JSONC（带注释 JSON）格式输出</td><td><code>fastfetch --format jsonc</code></td></tr><tr><td><code>fastfetch --list-presets</code></td><td>列出所有内置配置预设</td><td><code>fastfetch --list-presets</code></td></tr><tr><td><code>fastfetch --preset &lt;name&gt;</code></td><td>使用指定预设配置</td><td><code>fastfetch --preset mac</code></td></tr><tr><td><code>fastfetch --config &lt;path&gt;</code></td><td>使用自定义配置文件</td><td><code>fastfetch --config ~/.config/fastfetch/config.jsonc</code></td></tr><tr><td><code>fastfetch --help</code></td><td>显示完整帮助信息</td><td><code>fastfetch --help</code></td></tr><tr><td><code>fastfetch --version</code></td><td>显示版本号</td><td><code>fastfetch --version</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-基础使用-默认输出" tabindex="-1"><a class="header-anchor" href="#示例-1-基础使用-默认输出" aria-hidden="true">#</a> 示例 1：基础使用（默认输出）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 直接在终端运行，查看本机系统信息</span>
fastfetch
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>运行后终端会显示类似下面的输出：操作系统、主机名、内核版本、Uptime、CPU、GPU、内存、磁盘、终端、Shell 等信息，左侧带苹果 logo（macOS 上）。</p><h3 id="示例-2-隐藏-logo-只显示信息" tabindex="-1"><a class="header-anchor" href="#示例-2-隐藏-logo-只显示信息" aria-hidden="true">#</a> 示例 2：隐藏 Logo，只显示信息</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 某些场景下（如脚本日志中）不需要 logo，可以隐藏</span>
fastfetch <span class="token parameter variable">--logo</span> none
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>输出将不再显示 ASCII 艺术 logo，只保留各项系统信息，适合嵌入脚本或管道处理。</p><h3 id="示例-3-以-json-格式输出供脚本解析" tabindex="-1"><a class="header-anchor" href="#示例-3-以-json-格式输出供脚本解析" aria-hidden="true">#</a> 示例 3：以 JSON 格式输出供脚本解析</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 将系统信息导出为 JSON，交给 jq 等工具处理</span>
fastfetch <span class="token parameter variable">--format</span> json <span class="token operator">|</span> jq <span class="token string">&#39;.host&#39;</span>           <span class="token comment"># 提取主机名等信息</span>
fastfetch <span class="token parameter variable">--format</span> json <span class="token operator">|</span> jq <span class="token string">&#39;.cpu&#39;</span>            <span class="token comment"># 提取 CPU 信息</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这会输出结构化的 JSON 数据，方便在 shell 脚本、CI 流程中自动化采集系统信息。</p><h3 id="示例-4-生成自定义配置文件" tabindex="-1"><a class="header-anchor" href="#示例-4-生成自定义配置文件" aria-hidden="true">#</a> 示例 4：生成自定义配置文件</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 首次生成默认配置文件到标准位置，然后编辑</span>
fastfetch --gen-config

<span class="token comment"># 查看生成位置（macOS/Linux 常见路径）</span>
<span class="token function">cat</span> ~/.config/fastfetch/config.jsonc
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>--gen-config</code> 会在 <code>~/.config/fastfetch/config.jsonc</code> 生成一份带完整注释的默认配置，你可以在此基础上修改 logo、模块顺序、显示样式等。</p><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><h3 id="_1-使用预设快速切换外观" tabindex="-1"><a class="header-anchor" href="#_1-使用预设快速切换外观" aria-hidden="true">#</a> 1. 使用预设快速切换外观</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 查看所有可用预设</span>
fastfetch --list-presets

<span class="token comment"># 使用 macOS 风格预设</span>
fastfetch <span class="token parameter variable">--preset</span> mac
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>预设文件位于 fastfetch 安装目录下的 <code>presets/</code> 目录中（可通过 <code>brew --prefix fastfetch</code> 查看安装路径）。你也可以将自己的配置以 <code>*.jsonc</code> 放入 <code>~/.config/fastfetch/</code> 目录，用 <code>--preset 文件名</code> 调用。</p><h3 id="_2-结合-shell-启动文件自动展示" tabindex="-1"><a class="header-anchor" href="#_2-结合-shell-启动文件自动展示" aria-hidden="true">#</a> 2. 结合 shell 启动文件自动展示</h3><p>在 <code>~/.zshrc</code> 或 <code>~/.bashrc</code> 末尾追加一行，登录终端时自动显示系统信息：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>fastfetch <span class="token parameter variable">--logo</span> none
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>因为 fastfetch 启动极快（毫秒级），不会明显拖慢 shell 启动速度。</p><h3 id="_3-模块结构自定义" tabindex="-1"><a class="header-anchor" href="#_3-模块结构自定义" aria-hidden="true">#</a> 3. 模块结构自定义</h3><p>配置文件中的 <code>structure</code> 字段控制显示顺序与内容，例如只显示常用模块：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>fastfetch <span class="token parameter variable">--structure</span> OS:Host:Uptime:Kernel:CPU:Memory:Shell
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>你还可以在配置文件中为每个模块单独设置颜色、标签（key）、是否显示等细节。</p><h3 id="_4-环境变量与主题色" tabindex="-1"><a class="header-anchor" href="#_4-环境变量与主题色" aria-hidden="true">#</a> 4. 环境变量与主题色</h3><p>fastfetch 支持通过环境变量调整部分行为，例如：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 强制输出无颜色（用于管道或日志）</span>
<span class="token assign-left variable">NO_COLOR</span><span class="token operator">=</span><span class="token number">1</span> fastfetch

<span class="token comment"># 设置终端列数/宽度以调整 logo 缩放</span>
<span class="token assign-left variable"><span class="token environment constant">COLUMNS</span></span><span class="token operator">=</span><span class="token number">80</span> fastfetch
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>同时支持 <code>--title-color</code>、<code>--key-color</code> 等参数控制输出配色，可配合终端主题做统一风格。</p><h3 id="_5-深入-配置文件逐模块精调" tabindex="-1"><a class="header-anchor" href="#_5-深入-配置文件逐模块精调" aria-hidden="true">#</a> 5. 深入：配置文件逐模块精调</h3><p><code>fastfetch --gen-config</code> 生成的默认 <code>config.jsonc</code> 是理解 fastfetch 配置的最佳入口。核心结构如下（JSONC 支持 <code>//</code> 注释与尾逗号）：</p><div class="language-jsonc line-numbers-mode" data-ext="jsonc"><pre class="language-jsonc"><code>// ~/.config/fastfetch/config.jsonc
{
  &quot;$schema&quot;: &quot;https://github.com/fastfetch-cli/fastfetch/raw/dev/doc/json_schema.json&quot;,
  &quot;logo&quot;: {
    &quot;type&quot;: &quot;auto&quot;,          // auto / small / tiny / none / 具体路径
    &quot;color&quot;: {
      &quot;type&quot;: &quot;auto&quot;          // auto 跟随主题 / 指定颜色名 / 十六进制
    },
    &quot;padding&quot;: { &quot;top&quot;: 0, &quot;left&quot;: 0 }
  },
  &quot;display&quot;: {
    &quot;separator&quot;: &quot; → &quot;,       // 键与值之间的分隔符
    &quot;color&quot;: {
      &quot;keys&quot;: &quot;green&quot;,        // 左侧 key 的颜色
      &quot;values&quot;: &quot;default&quot;     // 右侧 value 的颜色
    }
  },
  &quot;modules&quot;: [
    { &quot;type&quot;: &quot;title&quot;, &quot;color&quot;: { &quot;title&quot;: &quot;cyan&quot; } },
    { &quot;type&quot;: &quot;os&quot;, &quot;key&quot;: &quot;OS&quot; },
    { &quot;type&quot;: &quot;host&quot;, &quot;key&quot;: &quot;Host&quot; },
    { &quot;type&quot;: &quot;cpu&quot;, &quot;key&quot;: &quot;CPU&quot; },
    { &quot;type&quot;: &quot;memory&quot;, &quot;key&quot;: &quot;Memory&quot; },
    { &quot;type&quot;: &quot;break&quot; }        // 换行，控制左右布局
  ]
}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>常用模块 type 一览</strong>：<code>title</code>、<code>separator</code>、<code>os</code>、<code>host</code>、<code>kernel</code>、<code>uptime</code>、<code>cpu</code>、<code>gpu</code>、<code>memory</code>、<code>disk</code>、<code>display</code>（分辨率）、<code>terminal</code>、<code>terminalfont</code>、<code>shell</code>、<code>wm</code>、<code>de</code>、<code>theme</code>、<code>icons</code>、<code>font</code>、<code>localip</code>、<code>publicip</code>、<code>break</code>（换行）、<code>blank</code>（空行）。</p><p><strong>给某个模块改标签与颜色</strong>：</p><div class="language-jsonc line-numbers-mode" data-ext="jsonc"><pre class="language-jsonc"><code>{ &quot;type&quot;: &quot;cpu&quot;, &quot;key&quot;: &quot;处理器&quot;, &quot;color&quot;: { &quot;key&quot;: &quot;yellow&quot; } }
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>临时用命令行覆盖配置</strong>（不改文件）比改配置更快，适合试效果：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 只改分隔符 + 键颜色</span>
fastfetch <span class="token parameter variable">--separator</span> <span class="token string">&#39; → &#39;</span> --key-color yellow

<span class="token comment"># 只显示指定模块</span>
fastfetch <span class="token parameter variable">--structure</span> OS:CPU:Memory <span class="token parameter variable">--logo</span> small
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-深入-自定义-logo-ascii-艺术-图片" tabindex="-1"><a class="header-anchor" href="#_6-深入-自定义-logo-ascii-艺术-图片" aria-hidden="true">#</a> 6. 深入：自定义 Logo（ASCII 艺术 / 图片）</h3><p>fastfetch 的 logo 高度灵活，是&quot;个性化&quot;的重头戏。常用四种方式：</p><p><strong>① 用内置 logo 类型</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>fastfetch <span class="token parameter variable">--logo</span> small            <span class="token comment"># 缩小版系统 logo</span>
fastfetch <span class="token parameter variable">--logo</span> tiny             <span class="token comment"># 最小 logo</span>
fastfetch <span class="token parameter variable">--logo</span> none             <span class="token comment"># 隐藏 logo</span>
fastfetch <span class="token parameter variable">--logo</span> retro            <span class="token comment"># 复古风格</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>② 用一张图片作为 logo（需装 <code>chafa</code>）</strong></p><p><code>chafa</code> 能把图片转成终端字符画。fastfetch 检测到图片路径时会调用它渲染：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># brew install chafa</span>
fastfetch <span class="token parameter variable">--logo</span> /path/to/your.png

<span class="token comment"># 在配置文件里写死</span>
<span class="token comment"># &quot;logo&quot;: { &quot;type&quot;: &quot;/home/me/pics/logo.png&quot;, &quot;width&quot;: 40 }</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>③ 自定义 ASCII 文字 logo</strong></p><p>用 <code>toilet</code> 或 <code>figlet</code> 把文字生成 ASCII 艺术，再喂给 fastfetch：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># brew install toilet</span>
<span class="token comment"># 生成文字 logo（showfigfonts 可列出字体）</span>
toilet <span class="token parameter variable">-f</span> mono12 <span class="token parameter variable">-F</span> metal <span class="token string">&quot;MYHOST&quot;</span> <span class="token operator">&gt;</span> ~/.config/fastfetch/mylogo.txt

<span class="token comment"># 在配置里指定该文字文件</span>
<span class="token comment"># &quot;logo&quot;: { &quot;type&quot;: &quot;/Users/wangbo/.config/fastfetch/mylogo.txt&quot; }</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>④ 手写一个纯文本 logo 文件</strong></p><p>logo 文件就是普通文本，一行行摆放字符即可，换行控制高度，空格控制宽度：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># ~/.config/fastfetch/neko.txt
 /\\_/\\
( o.o )
 &gt; ^ &lt;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>给 logo 上色</strong>（在配置或命令行）：fastfetch 的 logo 颜色跟随主题自动取色，也可显式指定：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 命令行指定 logo 颜色（颜色名 / 十六进制均可）</span>
fastfetch --logo-color cyan
fastfetch --logo-color <span class="token string">&#39;#ff5500&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-深入-模块级颜色与-theme-色" tabindex="-1"><a class="header-anchor" href="#_7-深入-模块级颜色与-theme-色" aria-hidden="true">#</a> 7. 深入：模块级颜色与 theme 色</h3><p>fastfetch 没有独立&quot;主题文件&quot;，但可用 <code>.jsonc</code> 配置文件充当&quot;主题&quot;——把整套颜色/logo/结构存成一个文件，随 <code>--preset</code> 或 <code>--config</code> 切换：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 存一份&quot;浅色终端主题&quot;配置</span>
fastfetch <span class="token parameter variable">--structure</span> OS:CPU:Memory --key-color black <span class="token parameter variable">--logo</span> small <span class="token operator">&gt;</span> /dev/null

<span class="token comment"># 做成两个预设文件，写进 ~/.config/fastfetch/：</span>
<span class="token comment">#   light.jsonc / dark.jsonc，用 --preset light / --preset dark 切换</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>给不同模块配置不同颜色</strong>的完整示例（写入配置文件的 <code>modules</code>）：</p><div class="language-jsonc line-numbers-mode" data-ext="jsonc"><pre class="language-jsonc"><code>{ &quot;type&quot;: &quot;title&quot;,   &quot;color&quot;: { &quot;title&quot;: &quot;cyan&quot; } }
{ &quot;type&quot;: &quot;os&quot;,      &quot;color&quot;: { &quot;key&quot;: &quot;yellow&quot;, &quot;value&quot;: &quot;default&quot; } }
{ &quot;type&quot;: &quot;memory&quot;,  &quot;color&quot;: { &quot;key&quot;: &quot;magenta&quot; } }
{ &quot;type&quot;: &quot;disk&quot;,    &quot;color&quot;: { &quot;value&quot;: &quot;blue&quot; } }
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-深入-模块级性能与隐私" tabindex="-1"><a class="header-anchor" href="#_8-深入-模块级性能与隐私" aria-hidden="true">#</a> 8. 深入：模块级性能与隐私</h3><p>fastfetch 采集信息时会执行系统命令（如 <code>sysctl</code>、<code>sw_vers</code>、<code>system_profiler</code> 等），个别模块可能有轻微开销或涉及隐私：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 用 --structure 只保留必要的，能省去无关采集</span>
fastfetch <span class="token parameter variable">--structure</span> OS:CPU:Memory

<span class="token comment"># 不想显示本机 IP 等隐私信息，就不要放 localip / publicip 模块</span>
<span class="token comment"># 需要公网 IP 的模块会发起网络请求，离线/隐私场景直接删掉</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_9-常用启动别名" tabindex="-1"><a class="header-anchor" href="#_9-常用启动别名" aria-hidden="true">#</a> 9. 常用启动别名</h3><p>把个性化结果固化成别名，一键切换风格：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># ~/.zshrc</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">ff</span><span class="token operator">=</span><span class="token string">&#39;fastfetch&#39;</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">ffmini</span><span class="token operator">=</span><span class="token string">&#39;fastfetch --logo small&#39;</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">ffnone</span><span class="token operator">=</span><span class="token string">&#39;fastfetch --logo none&#39;</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">ffjson</span><span class="token operator">=</span><span class="token string">&#39;fastfetch --format json&#39;</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">ffmac</span><span class="token operator">=</span><span class="token string">&#39;fastfetch --preset mac&#39;</span>
<span class="token builtin class-name">alias</span> <span class="token assign-left variable">ffosx</span><span class="token operator">=</span><span class="token string">&#39;fastfetch --structure OS:CPU:Memory --separator &quot; &quot; --key-color yellow&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><h3 id="_1-首次运行缺少字体导致-logo-错位" tabindex="-1"><a class="header-anchor" href="#_1-首次运行缺少字体导致-logo-错位" aria-hidden="true">#</a> 1. 首次运行缺少字体导致 Logo 错位</h3><p>ASCII logo 对齐依赖等宽字体。如果 logo 出现错位，先检查终端是否使用等宽字体（如 Menlo、JetBrains Mono、Fira Code），或者直接使用 <code>fastfetch --logo none</code> 跳过 logo。</p><h3 id="_2-json-输出与默认输出差异" tabindex="-1"><a class="header-anchor" href="#_2-json-输出与默认输出差异" aria-hidden="true">#</a> 2. JSON 输出与默认输出差异</h3><p><code>--format json</code> 输出的是原始数据（键名小写），与默认的人类可读输出字段并不完全一一对应。脚本解析时建议先 <code>fastfetch --format json</code> 查看实际字段名，再编写解析逻辑。</p><h3 id="_3-配置文件语法" tabindex="-1"><a class="header-anchor" href="#_3-配置文件语法" aria-hidden="true">#</a> 3. 配置文件语法</h3><p>配置文件为 JSONC（JSON with Comments）格式，支持 <code>//</code> 注释和尾逗号。如果你手动编辑时用了标准 JSON 且带注释，fastfetch 会报解析错误——务必使用 JSONC 语法。</p><h3 id="_4-性能与频率" tabindex="-1"><a class="header-anchor" href="#_4-性能与频率" aria-hidden="true">#</a> 4. 性能与频率</h3><p>fastfetch 本身很轻量，但若在 shell 启动文件中每次打开终端都运行，频繁刷新磁盘/内核信息仍会有少量开销。建议只在交互式登录 shell 中调用，不要放进非交互式脚本（可用 <code>[[ $- == *i* ]]</code> 判断）的默认路径里。</p><h3 id="_5-版本与升级" tabindex="-1"><a class="header-anchor" href="#_5-版本与升级" aria-hidden="true">#</a> 5. 版本与升级</h3><p>brew 升级后若遇到输出异常，先运行 <code>fastfetch --version</code> 确认版本。如从旧版本升级后配置不兼容，可备份后删除 <code>~/.config/fastfetch/</code> 重新生成默认配置，再按需调整。</p><h3 id="_6-图片-logo-相关报错" tabindex="-1"><a class="header-anchor" href="#_6-图片-logo-相关报错" aria-hidden="true">#</a> 6. 图片 logo 相关报错</h3><table><thead><tr><th>现象</th><th>原因</th><th>解决办法</th></tr></thead><tbody><tr><td><code>--logo &lt;图片&gt;</code> 无输出或乱码</td><td>未装 <code>chafa</code>，或终端不支持真彩</td><td><code>brew install chafa</code>；或换 ASCII 文字 logo</td></tr><tr><td>图片缩放失真/超出屏宽</td><td>未设 <code>width</code>/<code>height</code></td><td>配置里给 logo 加 <code>&quot;width&quot;: 40</code>，或命令行用 <code>--logo-width 40</code></td></tr><tr><td>图片 logo 太占面积</td><td>图比信息区还大</td><td>用 <code>--logo-small</code>，或调小 <code>width</code></td></tr></tbody></table><h3 id="_7-换行-布局错乱" tabindex="-1"><a class="header-anchor" href="#_7-换行-布局错乱" aria-hidden="true">#</a> 7. 换行/布局错乱</h3><p><code>break</code> 模块（换行）位置决定左右布局。若信息挤在一侧或混行，检查配置里 <code>break</code>/<code>blank</code> 模块的位置，或命令行用 <code>--structure</code> 显式控制顺序。</p><h3 id="_8-安全注意点" tabindex="-1"><a class="header-anchor" href="#_8-安全注意点" aria-hidden="true">#</a> 8. 安全注意点</h3><ul><li><code>publicip</code> 模块会发起<strong>公网请求</strong>暴露本机出口 IP，涉及隐私或离线环境时<strong>不要</strong>放进默认配置。</li><li>在共享/展示终端截图时，<code>host</code>、<code>localip</code>、<code>publicip</code> 可能泄露主机名与内网/公网地址，截图前按需精简 <code>structure</code>。</li></ul><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><h3 id="_1-脚本集成-把系统信息喂给-shell-脚本" tabindex="-1"><a class="header-anchor" href="#_1-脚本集成-把系统信息喂给-shell-脚本" aria-hidden="true">#</a> 1. 脚本集成：把系统信息喂给 shell 脚本</h3><p>fastfetch 的 <code>--format json</code> 是脚本友好的核心。配合 <code>jq</code> 可抽取任意字段：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 抽取 CPU 型号</span>
fastfetch <span class="token parameter variable">--format</span> json <span class="token operator">|</span> jq <span class="token parameter variable">-r</span> <span class="token string">&#39;.cpu&#39;</span>

<span class="token comment"># 抽取内存总量（以可读字符串输出）</span>
fastfetch <span class="token parameter variable">--format</span> json <span class="token operator">|</span> jq <span class="token parameter variable">-r</span> <span class="token string">&#39;.memory&#39;</span>

<span class="token comment"># 抽取磁盘使用（第一个盘符）</span>
fastfetch <span class="token parameter variable">--format</span> json <span class="token operator">|</span> jq <span class="token parameter variable">-r</span> <span class="token string">&#39;.disk[0]&#39;</span>

<span class="token comment"># 组装成一行摘要（供写入日志/横幅）</span>
<span class="token assign-left variable">SUMMARY</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>fastfetch <span class="token parameter variable">--format</span> json <span class="token operator">|</span> jq <span class="token parameter variable">-r</span> <span class="token string">&#39;[.os, .host, .cpu, .memory] | join(&quot; | &quot;)&#39;</span><span class="token variable">)</span></span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$SUMMARY</span>&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-写进-shell-启动文件-个性化欢迎横幅" tabindex="-1"><a class="header-anchor" href="#_2-写进-shell-启动文件-个性化欢迎横幅" aria-hidden="true">#</a> 2. 写进 shell 启动文件（个性化欢迎横幅）</h3><p>在 <code>~/.zshrc</code> / <code>~/.bashrc</code> 末尾追加，登录即显示带自定义 logo 的欢迎界面：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 只读交互式 shell 触发（非交互脚本不显示）</span>
<span class="token keyword">if</span> <span class="token punctuation">[</span><span class="token punctuation">[</span> $- <span class="token operator">==</span> *i* <span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span>
  fastfetch <span class="token parameter variable">--logo</span> small
<span class="token keyword">fi</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>配合自定义 ASCII logo 文件，每次打开终端都是专属&quot;开机画面&quot;。</p><h3 id="_3-与-figlet-toilet-组合做动态-banner" tabindex="-1"><a class="header-anchor" href="#_3-与-figlet-toilet-组合做动态-banner" aria-hidden="true">#</a> 3. 与 <code>figlet</code> / <code>toilet</code> 组合做动态 banner</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 先用 toilet 生成当前时间/日期的文字 logo，再让 fastfetch 显示</span>
<span class="token comment"># 生成一个&quot;今日&quot;文字 logo</span>
toilet <span class="token parameter variable">-f</span> mono12 <span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span><span class="token function">date</span> +%m月%d日<span class="token variable">)</span></span>&quot;</span> <span class="token operator">&gt;</span> ~/.config/fastfetch/today.txt
<span class="token comment"># 用这张动态生成的 logo 显示</span>
fastfetch <span class="token parameter variable">--logo</span> ~/.config/fastfetch/today.txt
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-写进-makefile-做-环境信息快照" tabindex="-1"><a class="header-anchor" href="#_4-写进-makefile-做-环境信息快照" aria-hidden="true">#</a> 4. 写进 Makefile 做&quot;环境信息快照&quot;</h3><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code><span class="token comment"># Makefile</span>
<span class="token builtin-target builtin">.PHONY</span><span class="token punctuation">:</span> info snapshot

<span class="token comment"># 显示本机信息</span>
<span class="token target symbol">info</span><span class="token punctuation">:</span>
	<span class="token operator">@</span>fastfetch

<span class="token comment"># 导出 JSON 快照到文件，供后续脚本消费</span>
<span class="token target symbol">snapshot</span><span class="token punctuation">:</span>
	<span class="token operator">@</span>mkdir -p .meta
	<span class="token operator">@</span>fastfetch --format json &gt; .meta/sysinfo_<span class="token variable">$$</span><span class="token punctuation">(</span>date +%Y%m%d_%H%M%S<span class="token punctuation">)</span>.json
	<span class="token operator">@</span>echo <span class="token string">&quot;已写入 .meta/&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-ci-集成-采集-runner-环境信息" tabindex="-1"><a class="header-anchor" href="#_5-ci-集成-采集-runner-环境信息" aria-hidden="true">#</a> 5. CI 集成：采集 runner 环境信息</h3><p>在 GitHub Actions / GitLab CI 里用 fastfetch 记录构建环境，便于复现问题：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token comment"># .github/workflows/ci.yml（片段）</span>
<span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> 采集运行环境信息
  <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
    fastfetch --version
    fastfetch --format json | jq &#39;{os: .os, cpu: .cpu, memory: .memory}&#39; \\
      &gt; env-snapshot.json</span>
<span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> 上传环境快照
  <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/upload<span class="token punctuation">-</span>artifact@v4
  <span class="token key atrule">with</span><span class="token punctuation">:</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span> env<span class="token punctuation">-</span>snapshot
    <span class="token key atrule">path</span><span class="token punctuation">:</span> env<span class="token punctuation">-</span>snapshot.json
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-与-neofetch-screenfetch-对比与迁移" tabindex="-1"><a class="header-anchor" href="#_6-与-neofetch-screenfetch-对比与迁移" aria-hidden="true">#</a> 6. 与 <code>neofetch</code>/<code>screenfetch</code> 对比与迁移</h3><p>从 neofetch 迁移过来时，注意：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># neofetch 用 --ascii_distro 指定发行版，fastfetch 用 --logo</span>
fastfetch <span class="token parameter variable">--logo</span> arch        <span class="token comment"># 指定显示某发行版 logo</span>
<span class="token comment"># neofetch 的 --off 隐藏 logo，fastfetch 用 --logo none</span>

<span class="token comment"># 列出 fastfetch 支持的所有 logo 名称（用于 --logo）</span>
fastfetch --list-logos <span class="token operator">|</span> <span class="token function">head</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-生产级实践建议" tabindex="-1"><a class="header-anchor" href="#_7-生产级实践建议" aria-hidden="true">#</a> 7. 生产级实践建议</h3><ul><li><strong>让 <code>--format json</code> 成为脚本标准接口</strong>：一切自动化采集（CI、日志、监控）都走 JSON，别解析彩色人类文本。</li><li><strong>用配置文件取代一堆命令行参数</strong>：把 logo、颜色、结构沉淀进 <code>~/.config/fastfetch/config.jsonc</code>，多机同步，处处一致。</li><li><strong>自定义 logo 纳入 dotfiles 仓库</strong>：ASCII logo 文件、图片、配置文件一起版本管理，换机一键恢复。</li><li><strong>区分&quot;交互欢迎&quot;与&quot;脚本取数&quot;两套</strong>：交互式 shell 用带 logo 的美观配置；脚本/cron 用 <code>--format json</code> 精简结构，互不干扰。</li><li><strong>控制采集副作用</strong>：默认配置里避免 <code>publicip</code>（公网请求）等有副作用/隐私模块，确需时按场景临时开启。</li><li><strong>升级后重新 <code>--gen-config</code> 对比</strong>：每次 brew 升级后跑一次 <code>fastfetch --gen-config --config /tmp/newcfg.jsonc</code> 与旧配置 diff，及时发现新增/变更字段。</li></ul>`,109),c=[o];function i(d,l){return a(),s("div",null,c)}const u=e(t,[["render",i],["__file","fastfetch.html.vue"]]);export{u as default};
